import{_ as e}from"./chunks/merge.ZJ0pW7Ba.js";import{_ as o,o as r,c as a,a4 as s}from"./chunks/framework.bruR1JhL.js";const n="/tilepress/screenshots/merge-light.webp",f=JSON.parse('{"title":"The Tilepress window","description":"The Explorer, the tools, the Preview, the action bar and Saved card, Find a tool, History, the status panel and keyboard shortcuts.","frontmatter":{"title":"The Tilepress window","description":"The Explorer, the tools, the Preview, the action bar and Saved card, Find a tool, History, the status panel and keyboard shortcuts."},"headers":[],"relativePath":"docs/interface.md","filePath":"docs/interface.md","lastUpdated":1795509372000}'),i={name:"docs/interface.md"};function d(h,t,l,p,g,c){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="the-tilepress-window" tabindex="-1">The Tilepress window <a class="header-anchor" href="#the-tilepress-window" aria-label="Permalink to &quot;The Tilepress window&quot;">​</a></h1><p>The window has three panels side by side:</p><p><img src="'+e+'" alt="The Tilepress window: the Explorer on the left, Merge PDF in the middle, the Preview on the right"></p><ul><li>the <strong>Explorer</strong> on the left, for finding files and folders;</li><li>the <strong>tools</strong> in the middle, with the top bar above them and a status bar below;</li><li>the <strong>Preview</strong> on the right, showing whatever is selected in the Explorer.</li></ul><h2 id="the-top-bar" tabindex="-1">The top bar <a class="header-anchor" href="#the-top-bar" aria-label="Permalink to &quot;The top bar&quot;">​</a></h2><p>From left to right, the top bar holds:</p><table tabindex="0"><thead><tr><th>Part</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Documents</strong> / <strong>Images</strong></td><td>Switches between the two sections. Documents has the PDF tools and LaTeX; Images has the image tools.</td></tr><tr><td>Category tabs</td><td>The categories of the current section. Hover over a tab for its full name.</td></tr><tr><td><strong>Find a tool</strong></td><td>Opens a search box for every tool. Also <kbd>Ctrl</kbd>+<kbd>K</kbd>. See <a href="#find-a-tool">Find a tool</a>.</td></tr><tr><td><strong>History</strong> (clock icon)</td><td>Lists the files your tools have made. See <a href="/tilepress/docs/history">History</a>.</td></tr><tr><td>Status button (dot and <strong>Ready</strong>)</td><td>Opens the About box with the version and engines. See <a href="#the-status-button-and-about-box">The status button</a>.</td></tr><tr><td>Panel button</td><td><strong>Hide preview</strong> / <strong>Show preview</strong>.</td></tr></tbody></table><p>The category tabs are:</p><table tabindex="0"><thead><tr><th>Section</th><th>Tab</th><th>Full name</th><th>Docs</th></tr></thead><tbody><tr><td>Documents</td><td><strong>Pages</strong></td><td>Combine, Split &amp; Page Management</td><td><a href="/tilepress/docs/pdf-pages">Combine, split &amp; pages</a></td></tr><tr><td>Documents</td><td><strong>To PDF</strong></td><td>Conversion: To PDF</td><td><a href="/tilepress/docs/to-pdf">Convert to PDF</a></td></tr><tr><td>Documents</td><td><strong>From PDF</strong></td><td>Conversion: From PDF</td><td><a href="/tilepress/docs/from-pdf">Convert from PDF</a></td></tr><tr><td>Documents</td><td><strong>Edit &amp; Forms</strong></td><td>Editing, Forms &amp; Text Recognition</td><td><a href="/tilepress/docs/edit">Edit, forms &amp; OCR</a></td></tr><tr><td>Documents</td><td><strong>Security</strong></td><td>Security, Signatures &amp; Optimization</td><td><a href="/tilepress/docs/security">Security, signing &amp; size</a></td></tr><tr><td>Documents</td><td><strong>Print</strong></td><td>Printing &amp; Output</td><td><a href="/tilepress/docs/print">Printing</a></td></tr><tr><td>Documents</td><td><strong>LaTeX</strong></td><td>LaTeX</td><td><a href="/tilepress/docs/latex">LaTeX</a></td></tr><tr><td>Images</td><td><strong>Optimize</strong></td><td>Format &amp; Size Optimization</td><td><a href="/tilepress/docs/img-optimize">Format &amp; size</a></td></tr><tr><td>Images</td><td><strong>Frame</strong></td><td>Framing, Layout &amp; Generation</td><td><a href="/tilepress/docs/img-layout">Crop, rotate &amp; capture</a></td></tr><tr><td>Images</td><td><strong>AI</strong></td><td>AI &amp; Smart Enhancements</td><td><a href="/tilepress/docs/img-ai">AI enhancements</a></td></tr><tr><td>Images</td><td><strong>Edit &amp; Brand</strong></td><td>Editing &amp; Branding</td><td><a href="/tilepress/docs/img-edit">Edit &amp; brand</a></td></tr></tbody></table><p>When the middle panel is narrow, the top bar saves space: the labels disappear and only the icons stay. Hover over an icon to see what it is.</p><h2 id="the-tool-strip" tabindex="-1">The tool strip <a class="header-anchor" href="#the-tool-strip" aria-label="Permalink to &quot;The tool strip&quot;">​</a></h2><p>Under the top bar, the tool strip shows the full name of the category and a button for each of its tools. Hover over a tool for a one-line description. Print and LaTeX have only one tool each, so they have no tool strip.</p><p>Tilepress remembers where you were: each section reopens its last category, and each category its last tool.</p><p>Switching tools doesn&#39;t lose your work. Every tool keeps its files and settings while you use other tools, until you close Tilepress.</p><h2 id="the-explorer" tabindex="-1">The Explorer <a class="header-anchor" href="#the-explorer" aria-label="Permalink to &quot;The Explorer&quot;">​</a></h2><p>The Explorer has three parts: <strong>Pinned</strong>, <strong>Locations</strong> and the folder tree. Click <strong>Pinned</strong> or <strong>Locations</strong> to fold that part away.</p><p>Two buttons sit in the Explorer header:</p><ul><li><strong>Show hidden items</strong> (the eye) shows files and folders that are hidden. Tilepress counts as hidden anything Windows marks as hidden or system, and names that start with a dot. Hidden items appear dimmed.</li><li><strong>Refresh</strong> reads the open folders again. You rarely need it: when a tool saves a file, the Explorer refreshes by itself.</li></ul><h3 id="pinned" tabindex="-1">Pinned <a class="header-anchor" href="#pinned" aria-label="Permalink to &quot;Pinned&quot;">​</a></h3><p>Your saved folders. To pin a folder:</p><ul><li>right-click it and choose <strong>Pin</strong>;</li><li>open it and click the pin button at the end of the path bar (<strong>Pin this folder</strong>);</li><li>click <strong>+</strong> (<strong>Pin a folder…</strong>) next to the Pinned heading and choose a folder;</li><li>or drag a folder from the tree onto the Pinned list, at the place you want it.</li></ul><p>Drag pins to reorder them, or right-click a pin and choose <strong>Move up</strong> or <strong>Move down</strong>. The right-click menu also has <strong>Open</strong>, <strong>Unpin</strong>, <strong>Open in File Explorer</strong> and <strong>Copy path</strong>. A pin whose folder no longer exists is struck through, and its tooltip says &quot;Folder not found&quot;.</p><h3 id="locations" tabindex="-1">Locations <a class="header-anchor" href="#locations" aria-label="Permalink to &quot;Locations&quot;">​</a></h3><p><strong>Home</strong>, <strong>Desktop</strong>, <strong>Documents</strong> and <strong>Downloads</strong>, followed by every drive. Desktop, Documents and Downloads point to the real folders even when OneDrive or your organisation has moved them. Click a location to show it in the tree.</p><h3 id="the-folder-tree" tabindex="-1">The folder tree <a class="header-anchor" href="#the-folder-tree" aria-label="Permalink to &quot;The folder tree&quot;">​</a></h3><p>The tree shows the current folder. Folders come first, then files, sorted so that &quot;file2&quot; comes before &quot;file10&quot;. Hover over an item to see its full path, size and last change.</p><ul><li><strong>Click</strong> a folder to expand or collapse it. Its contents are read when you expand it.</li><li><strong>Double-click</strong> a folder to make it the current folder, or a file to open it in its usual app.</li><li><strong>Right-click</strong> an item for its menu (see below).</li><li><strong>Drag</strong> a folder onto Pinned, or a file onto a tool.</li></ul><p>A folder with more than 5,000 items shows the first 5,000 and says so.</p><h3 id="the-path-bar" tabindex="-1">The path bar <a class="header-anchor" href="#the-path-bar" aria-label="Permalink to &quot;The path bar&quot;">​</a></h3><p>Above the tree:</p><ul><li><strong>Back</strong>, <strong>Forward</strong> and <strong>Up one level</strong> buttons.</li><li>Breadcrumbs: click any folder in the path to go there.</li><li>Click the path bar, or press <kbd>Ctrl</kbd>+<kbd>L</kbd>, to type a path. Press <kbd>Enter</kbd> to go there or <kbd>Esc</kbd> to cancel. You can use <code>~</code> for your home folder and Windows variables such as <code>%USERPROFILE%</code>. A drive letter on its own, such as <code>D:</code>, works too.</li><li>The pin button at the end pins or unpins the current folder.</li></ul><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><p>The <strong>Filter</strong> box under the path bar narrows the tree to names that contain what you type. It only searches the folders that are already open in the tree, not their unopened subfolders. A folder stays visible if something inside it matches. Press <kbd>Esc</kbd> or click × to clear the filter, and <kbd>↓</kbd> to move into the tree.</p><h3 id="right-click-menus" tabindex="-1">Right-click menus <a class="header-anchor" href="#right-click-menus" aria-label="Permalink to &quot;Right-click menus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You right-click</th><th>Menu</th></tr></thead><tbody><tr><td>A file</td><td><strong>Open</strong>, <strong>Show in File Explorer</strong>, the tools that fit the file, <strong>Copy path</strong></td></tr><tr><td>A folder or a location</td><td><strong>Open</strong>, <strong>Pin</strong> or <strong>Unpin</strong>, <strong>Open in File Explorer</strong>, <strong>Copy path</strong></td></tr><tr><td>A pin</td><td><strong>Open</strong>, <strong>Unpin</strong>, <strong>Move up</strong>, <strong>Move down</strong>, <strong>Open in File Explorer</strong>, <strong>Copy path</strong></td></tr><tr><td>An empty part of the tree</td><td><strong>Pin this folder</strong> or <strong>Unpin this folder</strong>, <strong>Refresh</strong>, <strong>Show hidden items</strong> or <strong>Hide hidden items</strong>, <strong>Open in File Explorer</strong>, <strong>Copy path</strong></td></tr></tbody></table><p>The tool entries for each file type are listed in <a href="/tilepress/docs/">Getting started</a>. Use <kbd>↑</kbd> and <kbd>↓</kbd> to move through a menu and <kbd>Esc</kbd> to close it.</p><h2 id="the-preview-pane" tabindex="-1">The Preview pane <a class="header-anchor" href="#the-preview-pane" aria-label="Permalink to &quot;The Preview pane&quot;">​</a></h2><p>The Preview shows the item selected in the Explorer, and follows along as you move through the tree with the arrow keys.</p><table tabindex="0"><thead><tr><th>Selection</th><th>What you see</th></tr></thead><tbody><tr><td>PDF</td><td>Every page, loaded as you scroll, with page numbers. The details add the title and the size of the first page in mm.</td></tr><tr><td>Image (PNG, JPEG, GIF, WebP, BMP, TIFF, ICO, SVG)</td><td>The picture, the right way up for photos taken with the camera turned. Click it to switch between fitted and actual size. The details add the colour mode, and the number of frames for an animation (the first frame is shown).</td></tr><tr><td>Text and code</td><td>The first 256 KB with line numbers, the number of lines, the encoding and the line endings. Tick <strong>Wrap</strong> to wrap long lines. Files with an unknown extension are shown this way if they look like text.</td></tr><tr><td>CSV and TSV</td><td>A table of the first 300 rows and up to 40 columns. For CSV files, commas, semicolons, tabs and `</td></tr><tr><td>Folder</td><td>How many folders and files are directly inside (not in subfolders), their total size, the most common file types, and the item that changed last. Very large folders are counted up to 20,000 items.</td></tr><tr><td>Anything else</td><td>The details only.</td></tr></tbody></table><p>Under the name, buttons act on the item:</p><ul><li><strong>Open</strong> opens a file in its usual app. For a folder, the button is <strong>Open in File Explorer</strong>.</li><li><strong>Show in folder</strong> opens File Explorer with the file selected.</li><li><strong>PDF tools</strong> (PDFs), <strong>Edit photo</strong> (images) and <strong>Convert to PDF</strong> (files a Convert to PDF tool accepts) open the file in that tool.</li><li><strong>Copy path</strong> copies the full path.</li></ul><p>At the bottom, the details list the type, size, modified and created dates, and the folder the item is in.</p><p>Close the Preview with its × button (<strong>Hide preview</strong>). Bring it back with the panel button at the right end of the top bar.</p><h2 id="working-in-a-tool" tabindex="-1">Working in a tool <a class="header-anchor" href="#working-in-a-tool" aria-label="Permalink to &quot;Working in a tool&quot;">​</a></h2><h3 id="opening-a-file" tabindex="-1">Opening a file <a class="header-anchor" href="#opening-a-file" aria-label="Permalink to &quot;Opening a file&quot;">​</a></h3><p>Until you give it a file, a tool shows a drop area with a button such as <strong>Open PDF…</strong> or <strong>Open image…</strong>, and a <strong>Use</strong> button for the file selected in the Explorer if it fits. <a href="/tilepress/docs/">Getting started</a> lists all the ways to open a file.</p><p>Once a file is open, a bar at the top shows its name, page count or pixel size, and file size. It has:</p><ul><li><strong>Use</strong> <em>name</em>, when a different suitable file is selected in the Explorer;</li><li><strong>Change…</strong> to pick another file;</li><li><strong>Close</strong> to put the file away.</li></ul><p>You can also drop another file from the Explorer onto that bar.</p><p>Tools that work on many files at once show a list instead, with buttons such as <strong>Add images…</strong> and <strong>Clear list</strong>, and × on each row to remove it.</p><h3 id="the-action-bar" tabindex="-1">The action bar <a class="header-anchor" href="#the-action-bar" aria-label="Permalink to &quot;The action bar&quot;">​</a></h3><p>The action bar runs along the bottom of each tool. It stays in view while you scroll, and sits at the bottom of the window when the tool is shorter than the window.</p><ul><li>On the left, it sums up what will happen, for example how many pages or files, or holds a related option.</li><li>On the right is the <strong>main button</strong> that runs the tool, for example <strong>Merge and save…</strong> or <strong>Compress 5 images</strong>. It stays greyed out until the tool has what it needs.</li></ul><p>A button whose label ends in &quot;…&quot; asks first where to save. Most open a Save dialog with a suggested name, made from the original name plus a word such as <code>_rotated</code>, in the original&#39;s folder. If that name is taken, the suggestion becomes <code>name (2)</code> and so on, so nothing is overwritten unless you choose to. Tools that write many files ask for a folder, or offer <strong>Save next to each file</strong> and <strong>Save in a folder</strong> with a <strong>Choose…</strong> button.</p><p>While a tool works, its button shows <strong>Working…</strong> and a progress bar appears. Long jobs show a percentage and what they&#39;re doing. If something goes wrong, the message appears in a red box above the action bar. Your original files are never changed.</p><h3 id="the-saved-card" tabindex="-1">The Saved card <a class="header-anchor" href="#the-saved-card" aria-label="Permalink to &quot;The Saved card&quot;">​</a></h3><p>When a tool has saved, a <strong>Saved</strong> card appears (<strong>Saved 3 files</strong> for several). For each new file it shows the name, the page count or pixel size, and the file size. Hover over a name to see its full path.</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>Opens the file in its usual app.</td></tr><tr><td><strong>Show in folder</strong></td><td>Opens File Explorer with the file selected.</td></tr><tr><td><strong>Keep editing this file</strong></td><td>Opens the new file in Tilepress, so you can take the next step on it. It appears when the result is a single PDF or image, in the tools that support it.</td></tr></tbody></table><p>Click × to dismiss the card. When a tool makes many files, the card lists the first 12 and says how many more there are. Every run is also recorded in the <a href="/tilepress/docs/history">History</a>.</p><h2 id="find-a-tool" tabindex="-1">Find a tool <a class="header-anchor" href="#find-a-tool" aria-label="Permalink to &quot;Find a tool&quot;">​</a></h2><p>Click <strong>Find a tool</strong> in the top bar or press <kbd>Ctrl</kbd>+<kbd>K</kbd>. Type any part of a tool&#39;s name, what it does, or its category, for example <em>merge</em>, <em>sign</em>, <em>word</em> or <em>ocr</em>. With several words, a tool must match all of them. Tools whose name starts with what you typed come first.</p><ul><li><kbd>↑</kbd> and <kbd>↓</kbd> move through the list; <kbd>Enter</kbd> opens the highlighted tool.</li><li><kbd>Esc</kbd>, <kbd>Ctrl</kbd>+<kbd>K</kbd> again, or a click outside closes the box.</li></ul><p>Each result shows its category tab, or <strong>Open</strong> for the tool you&#39;re in.</p><h2 id="the-status-button-and-about-box" tabindex="-1">The status button and About box <a class="header-anchor" href="#the-status-button-and-about-box" aria-label="Permalink to &quot;The status button and About box&quot;">​</a></h2><p>The status button in the top bar shows a dot and <strong>Ready</strong> once the window is connected to Tilepress&#39;s engine. Click it for the About box:</p><table tabindex="0"><thead><tr><th>Row</th><th>Shows</th></tr></thead><tbody><tr><td>Header</td><td>The version, and how fast the window talks to the engine.</td></tr><tr><td><strong>LaTeX</strong></td><td>The LaTeX engine in use, or the state of its first-run setup.</td></tr><tr><td><strong>OCR</strong></td><td>Tesseract (and how many languages it has) and the Windows OCR languages, or &quot;Not available&quot;.</td></tr><tr><td><strong>Office conversion</strong></td><td>The Microsoft Office apps found, or LibreOffice, or &quot;Not found&quot;.</td></tr><tr><td><strong>Python</strong>, <strong>System</strong>, <strong>Mode</strong></td><td>Version details, useful when you <a href="/tilepress/support">ask for help</a>.</td></tr></tbody></table><p>If the LaTeX setup failed, the About box has a <strong>Retry LaTeX setup</strong> button. Press <kbd>Esc</kbd> or click elsewhere to close it.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The bar at the bottom of the middle panel shows the path, size and last change of the item selected in the Explorer. During the first-run LaTeX setup, it also shows the progress, such as <strong>Downloading LaTeX engine… 40%</strong>.</p><h2 id="resizing-the-panels" tabindex="-1">Resizing the panels <a class="header-anchor" href="#resizing-the-panels" aria-label="Permalink to &quot;Resizing the panels&quot;">​</a></h2><p>Drag the gap between two panels to resize them. You can also click the gap (or move to it with <kbd>Tab</kbd>) and use <kbd>←</kbd> and <kbd>→</kbd>. Double-click the gap to go back to the default width. The tools in the middle always keep at least 460 pixels.</p><h2 id="light-and-dark-theme" tabindex="-1">Light and dark theme <a class="header-anchor" href="#light-and-dark-theme" aria-label="Permalink to &quot;Light and dark theme&quot;">​</a></h2><p>Tilepress follows the Windows app mode. It&#39;s light when apps are set to Light under <strong>Settings</strong> &gt; <strong>Personalization</strong> &gt; <strong>Colors</strong>, and dark otherwise. If you turn off <strong>Animation effects</strong> in the Windows accessibility settings, Tilepress turns off its animations too.</p><p><img src="'+n+'" alt="Tilepress in the light theme"></p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Shortcuts that work across the window:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Ctrl</kbd>+<kbd>K</kbd></td><td>Open or close Find a tool</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>L</kbd></td><td>Type a folder path in the Explorer</td></tr><tr><td><kbd>Alt</kbd>+<kbd>←</kbd> / <kbd>Alt</kbd>+<kbd>→</kbd></td><td>Back / forward in the Explorer (while it has the focus)</td></tr><tr><td><kbd>Esc</kbd></td><td>Close Find a tool, a menu, or the History or About box; clear the Explorer filter</td></tr></tbody></table><p>In the folder tree:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><kbd>↑</kbd> / <kbd>↓</kbd>, <kbd>Home</kbd> / <kbd>End</kbd></td><td>Move the selection</td></tr><tr><td><kbd>→</kbd></td><td>Expand a folder, or move into it if it&#39;s already expanded</td></tr><tr><td><kbd>←</kbd></td><td>Collapse a folder, or move to its parent</td></tr><tr><td><kbd>Enter</kbd></td><td>Open a file, or make a folder the current folder</td></tr><tr><td><kbd>Backspace</kbd></td><td>Go up one level</td></tr><tr><td>Letters</td><td>Jump to the next item whose name starts with what you type</td></tr><tr><td><kbd>Menu</kbd> key</td><td>Open the right-click menu of the selected item</td></tr></tbody></table><p>Some tools have shortcuts of their own, described on their pages: <a href="/tilepress/docs/pdf-pages">Organize PDF</a>, <a href="/tilepress/docs/edit">Edit PDF</a>, <a href="/tilepress/docs/security">Sign PDF</a>, the <a href="/tilepress/docs/latex">LaTeX editor</a>, the <a href="/tilepress/docs/img-edit">Photo editor</a> and <a href="/tilepress/docs/img-ai">Blur face</a>.</p><h2 id="what-tilepress-remembers" tabindex="-1">What Tilepress remembers <a class="header-anchor" href="#what-tilepress-remembers" aria-label="Permalink to &quot;What Tilepress remembers&quot;">​</a></h2><p>Between sessions, Tilepress keeps your pins, the last folder you were in, whether hidden items are shown, the widths of the Explorer and Preview, whether the Preview is open, and whether history is on. They&#39;re saved in <code>%LOCALAPPDATA%\\Tilepress\\settings.json</code>. See <a href="/tilepress/docs/privacy">Privacy</a> for everything else in that folder.</p>',82)])])}const m=o(i,[["render",d]]);export{f as __pageData,m as default};
